  await t.test('4.23: Security Audit: Subprocess PTY automation test documents that synthetic TTY input satisfies process.stdin.isTTY', () => {
    const baseProject = ProjectManager.loadProject(FIXTURE_PROJECT_PATH);
    const plan = createIdeCreativePlan(baseProject);
    const pending = ApprovalAuthority.createPendingRequest({ creativePlan: plan, project: baseProject });

    // Attack Scenario: Subprocess allocates a pseudo-terminal (pty) to spoof human interactive presence
    const ptySpoofScript = `
import pty, os, sys, time

master, slave = pty.openpty()
pid = os.fork()
if pid == 0:
    os.close(master)
    os.dup2(slave, 0)
    os.dup2(slave, 1)
    os.dup2(slave, 2)
    os.close(slave)
    os.execlp('node', 'node', 'bin/eme-confirm.js', 'approve', sys.argv[1])
else:
    os.close(slave)
    time.sleep(0.3)
    # Automated agent programmatically sends 'CONFIRM' through the PTY
    os.write(master, b'CONFIRM\\n')
    output = b''
    while True:
        try:
            chunk = os.read(master, 1024)
            if not chunk: break
            output += chunk
        except OSError:
            break
    os.close(master)
    print(output.decode('utf-8'))
`;
    const spoofRun = spawnSync('python3', ['-c', ptySpoofScript, pending.request_id], {
      cwd: PROJECT_ROOT,
      encoding: 'utf8'
    });
    // Record that POSIX PTY reports isTTY=true and issues token
    assert.equal(spoofRun.status, 0);
    assert.ok(spoofRun.stdout.includes('HUMAN APPROVAL GRANTED'));

    // Verify that the security threat model document exists and accurately describes this boundary
    const threatModelPath = path.resolve(PROJECT_ROOT, 'docs/security/APPROVAL_THREAT_MODEL.md');
    assert.ok(fs.existsSync(threatModelPath), 'Threat model documentation must exist');
    const docContent = fs.readFileSync(threatModelPath, 'utf8');
    assert.ok(docContent.includes('The POSIX Pseudo-Terminal (PTY) Boundary'));
  });

